import React, { useEffect, useState } from 'react';
import CarnetDetalle from './CarnetDetalle';
import { APP_CONFIG } from '../config';
import { getTrabajadores, getFichas, getAprendicesPorFicha } from '../services/api';
import './CarnetList.css';

const CarnetList = () => {
  const [trabajadores, setTrabajadores]               = useState([]);
  const [fichas, setFichas]                           = useState([]);
  const [aprendicesActivos, setAprendicesActivos]     = useState([]);
  const [fichaActiva, setFichaActiva]                 = useState(null);
  const [personaSeleccionada, setPersonaSeleccionada] = useState(null);
  const [busqueda, setBusqueda]                       = useState('');
  const [cargandoAprendices, setCargandoAprendices]   = useState(false);
  const [vistaActiva, setVistaActiva]                 = useState(null);
  const [rolesAbierto, setRolesAbierto]               = useState(false);

  // IDs de aprendices que asistieron — se llena desde la BD
  const [asistencias, setAsistencias] = useState(new Set());

  useEffect(() => {
    const fetchDatos = async () => {
      try {
        const [trabajadoresData, fichasData] = await Promise.all([
          getTrabajadores(),
          getFichas(),
        ]);
        const trabajadoresFormateados = trabajadoresData.map((t) => ({
          ...t,
          tipo: t.funcionario ? 'funcionario' : t.contratista ? 'contratista' : 'usuario',
          regional: 'Regional Santander',
          centro: 'Centro Industrial del Diseño',
        }));
        setTrabajadores(trabajadoresFormateados);
        setFichas(fichasData);
      } catch (error) {
        console.error('Error cargando datos:', error);
      }
    };
    fetchDatos();
  }, []);

  // ── SIMULACIÓN (comentada) ────────────────────────────────────
  // Descomentar solo para pruebas visuales sin BD
  // useEffect(() => {
  //   if (aprendicesActivos.length === 0) return;
  //   const intervalo = setInterval(() => {
  //     setAsistencias((prev) => {
  //       const nuevas = new Set(prev);
  //       const ids = aprendicesActivos.map((a) => a.id);
  //       for (let i = 0; i < 3; i++) {
  //         nuevas.add(ids[Math.floor(Math.random() * ids.length)]);
  //       }
  //       return nuevas;
  //     });
  //   }, 2000);
  //   return () => clearInterval(intervalo);
  // }, [aprendicesActivos]);

  // ── TODO: consulta real a la BD ───────────────────────────────
  // Cuando tengas el endpoint listo, descomenta esto y borra la simulación de arriba
  // useEffect(() => {
  //   if (!fichaActiva) return;
  //   const fetchAsistencias = async () => {
  //     const data = await getAsistenciasPorFicha(fichaActiva); // importar de api.js
  //     const ids = new Set(data.map((a) => a.aprendiz_id));
  //     setAsistencias(ids);
  //   };
  //   fetchAsistencias(); // carga inicial
  //   const intervalo = setInterval(fetchAsistencias, 2000); // refresca cada 2s
  //   return () => clearInterval(intervalo);
  // }, [fichaActiva]);

  const handleFichaClick = async (numero_ficha) => {
    if (fichaActiva === numero_ficha) {
      setFichaActiva(null);
      setAprendicesActivos([]);
      setPersonaSeleccionada(null);
      setAsistencias(new Set());
      return;
    }
    setFichaActiva(numero_ficha);
    setPersonaSeleccionada(null);
    setAsistencias(new Set());
    setCargandoAprendices(true);
    try {
      const data = await getAprendicesPorFicha(numero_ficha);
      const formateados = data.map((a) => ({
        ...a,
        tipo: 'aprendiz',
        regional: 'Regional Santander',
        centro: 'Centro Industrial del Diseño',
      }));
      setAprendicesActivos(formateados);
    } catch (error) {
      console.error('Error cargando aprendices:', error);
    } finally {
      setCargandoAprendices(false);
    }
  };

  const aprendicesFiltrados = aprendicesActivos.filter(
    (p) =>
      p.nombre?.toLowerCase().includes(busqueda.toLowerCase()) ||
      p.documento?.toString().includes(busqueda)
  );

  const funcionarios = trabajadores.filter((t) => t.tipo === 'funcionario');
  const contratistas = trabajadores.filter((t) => t.tipo === 'contratista');

  const renderTarjetas = (lista, tipo) => (
    <div className="admin-content">
      <div className="card-list">
        {lista.map((persona) => (
          <div
            key={`${tipo}-${persona.id}`}
            onClick={() => setPersonaSeleccionada(persona)}
            className={`card-wrapper ${personaSeleccionada?.id === persona.id ? 'active' : ''}`}
          >
            <div className="card">
              <div className="header"><img src="/logo.png" alt="Logo" className="logo" /></div>
              <div className="photo-section">
                <img
                  src={persona.foto ? `${APP_CONFIG.API_URL}/imagen/${persona.foto}` : '/predeterminado.png'}
                  alt={persona.nombre}
                  className="profile-photo"
                />
              </div>
              <div className="info">
                <p className="label">{tipo.toUpperCase()}</p>
                <hr />
                <p className="name">{persona.nombre?.toUpperCase()}</p>
                <p className="id">CC: {persona.documento} — RH: {persona.tipo_sangre || 'N/D'}</p>
                <p className="region">{persona.regional}</p>
                <p className="center">{persona.centro}<br />y la Manufactura</p>
              </div>
            </div>
          </div>
        ))}
      </div>
      {personaSeleccionada && (
        <div className="detail-panel animate-slide-in">
          <CarnetDetalle persona={personaSeleccionada} />
        </div>
      )}
    </div>
  );

  return (
    <div className="dashboard">

      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">
          <img src="/logo.png" alt="SENA" className="sidebar-logo-img" />
          <span className="sidebar-logo-text">CarnetApp</span>
        </div>

        <nav className="sidebar-nav">
          <div className="nav-item-group">
            <button
              className={`nav-item ${rolesAbierto ? 'open' : ''}`}
              onClick={() => setRolesAbierto(!rolesAbierto)}
            >
              <span>Roles</span>
              <span className={`nav-arrow ${rolesAbierto ? 'rotated' : ''}`}>▾</span>
            </button>

            {rolesAbierto && (
              <div className="nav-submenu">
                <button
                  className={`nav-sub-item ${vistaActiva === 'aprendices' ? 'active' : ''}`}
                  onClick={() => { setVistaActiva('aprendices'); setPersonaSeleccionada(null); }}
                >
                  Aprendices
                </button>
                <button
                  className={`nav-sub-item ${vistaActiva === 'funcionarios' ? 'active' : ''}`}
                  onClick={() => { setVistaActiva('funcionarios'); setPersonaSeleccionada(null); }}
                >
                  Funcionarios
                </button>
                <button
                  className={`nav-sub-item ${vistaActiva === 'contratistas' ? 'active' : ''}`}
                  onClick={() => { setVistaActiva('contratistas'); setPersonaSeleccionada(null); }}
                >
                  Contratistas
                </button>
              </div>
            )}
          </div>

          <button
            className={`nav-item ${vistaActiva === 'cargar' ? 'active' : ''}`}
            onClick={() => setVistaActiva('cargar')}
          >
            <span>Cargar Data</span>
          </button>
        </nav>
      </aside>

      {/* Contenido */}
      <main className="main-content">

        {!vistaActiva && (
          <div className="welcome-card">
            <div className="welcome-oval">
              <img src="/logo.png" alt="SENA" className="welcome-logo" />
              <h2>Bienvenido</h2>
              <p>Selecciona una opción del menú para comenzar</p>
            </div>
          </div>
        )}

        {/* Vista Aprendices */}
        {vistaActiva === 'aprendices' && (
          <div className="vista-panel">
            <div className="vista-header">
              <h1>Aprendices</h1>
              <p>Selecciona una ficha para ver sus aprendices</p>
            </div>

            <input
              type="text"
              placeholder="Buscar por nombre o documento..."
              value={busqueda}
              onChange={(e) => setBusqueda(e.target.value)}
              className="busqueda-input"
            />

            {fichas.length > 0 && (
              <div className="fichas-container">
                <label className="fichas-label" htmlFor="select-ficha">Selecciona una ficha:</label>
                <div className="fichas-select-wrapper">
                  <select
                    id="select-ficha"
                    className="fichas-select"
                    value={fichaActiva || ''}
                    onChange={(e) => {
                      const val = e.target.value;
                      if (!val) {
                        setFichaActiva(null);
                        setAprendicesActivos([]);
                        setPersonaSeleccionada(null);
                        setAsistencias(new Set());
                      } else {
                        handleFichaClick(val);
                      }
                    }}
                  >
                    <option value="">-- Elige una ficha --</option>
                    {fichas.map((f) => (
                      <option key={f.numero_ficha} value={f.numero_ficha}>
                        {f.numero_ficha} · {f.nombre_ficha}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            )}

            <div className="admin-content">
              <div className="card-list">
                {cargandoAprendices && <p className="cargando-texto">Cargando aprendices...</p>}
                {!cargandoAprendices && aprendicesFiltrados.map((persona) => (
                  <div
                    key={`asistencia-${persona.id}`}
                    className={persona.asistio_hoy ? 'asistio' : 'no-asistio'}
                  >
                    <div
                      onClick={() => setPersonaSeleccionada(persona)}
                      className={`card-wrapper ${personaSeleccionada?.id === persona.id ? 'active' : ''}`}
                    >
                      <div className="card">
                        <div className="header"><img src="/logo.png" alt="Logo" className="logo" /></div>
                        <div className="photo-section">
                          <img
                            src={persona.foto ? `${APP_CONFIG.API_URL}/imagen/${persona.foto}` : '/predeterminado.png'}
                            alt={persona.nombre}
                            className="profile-photo"
                          />
                        </div>
                        <div className="info">
                          <p className="label">APRENDIZ</p>
                          <hr />
                          <p className="name">{persona.nombre?.toUpperCase()}</p>
                          <p className="id">CC: {persona.documento} — RH: {persona.tipo_sangre || 'N/D'}</p>
                          <p className="region">{persona.regional}</p>
                          <p className="center">{persona.centro}<br />y la Manufactura</p>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
              {personaSeleccionada && (
                <div className="detail-panel animate-slide-in">
                  <CarnetDetalle persona={personaSeleccionada} />
                </div>
              )}
            </div>
          </div>
        )}

        {/* Vista Funcionarios */}
        {vistaActiva === 'funcionarios' && (
          <div className="vista-panel">
            <div className="vista-header">
              <h1>Funcionarios</h1>
              <p>{funcionarios.length} funcionarios registrados</p>
            </div>
            {renderTarjetas(funcionarios, 'funcionario')}
          </div>
        )}

        {/* Vista Contratistas */}
        {vistaActiva === 'contratistas' && (
          <div className="vista-panel">
            <div className="vista-header">
              <h1>Contratistas</h1>
              <p>{contratistas.length} contratistas registrados</p>
            </div>
            {renderTarjetas(contratistas, 'contratista')}
          </div>
        )}

        {/* Vista Cargar Data */}
        {vistaActiva === 'cargar' && (
          <div className="vista-panel">
            <div className="vista-header">
              <h1>Cargar Data</h1>
              <p>Sube el archivo Excel con los usuarios a registrar</p>
            </div>
            <form
              onSubmit={async (e) => {
                e.preventDefault();
                const archivo = e.target.archivo.files[0];
                if (!archivo) return alert('Selecciona un archivo primero.');
                const formData = new FormData();
                formData.append('archivo', archivo);
                try {
                  const response = await fetch(`${APP_CONFIG.API_URL}/api/carga-masiva`, {
                    method: 'POST',
                    body: formData,
                  });
                  if (!response.ok) throw new Error(await response.text());
                  alert('Carga masiva exitosa');
                  window.location.reload();
                } catch (err) {
                  alert('Error en carga masiva: ' + err.message);
                }
              }}
              className="carga-masiva-form"
            >
              <input type="file" name="archivo" accept=".xlsx,.csv" />
              <button type="submit">Subir Carga Masiva</button>
            </form>
          </div>
        )}

      </main>
    </div>
  );
};

export default CarnetList;
