// services/api.js
import axios from 'axios';
import { APP_CONFIG } from '../config';

//const API_URL = 'http://localhost:8000/api';
const API_URL = APP_CONFIG.API_URL+'/api';

// Crear una instancia de axios con el token si existe
const axiosInstance = axios.create({
  baseURL: API_URL,
});

// Interceptor para agregar el token en cada solicitud automáticamente
axiosInstance.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Función para iniciar sesión
export const login = async (email, password) => {
  const response = await axios.post(`${API_URL}/login`, {
    email,
    password,
  });
  return response;
};

// Obtener perfil del usuario autenticado
export const getPerfil = async () => {
  const response = await axiosInstance.get('/perfil');
  return response.data;
};

// Obtener todos los trabajadores
export const getTrabajadores = async () => {
  const response = await axiosInstance.get('/trabajadores');
  return response.data;
};
export const getAprendices = async () => {
  const response = await axiosInstance.get('/aprendices');
  return response.data;
};
// Lista de fichas con su nombre de programa
export const getFichas = async () => {
  const response = await axiosInstance.get('/aprendices/fichas');
  return response.data;
};

// Aprendices de una ficha específica
export const getAprendicesPorFicha = async (numero_ficha) => {
  const response = await axiosInstance.get(`/aprendices/fichas/${numero_ficha}`);
  return response.data;
};
